/// <summary>
/// Manually trigger the data event handlers for the retail instance attribute values form when the attribute value is updated from the form. ecoResValue is required to trigger the necessary business events for downstream processing.
/// </summary>
[ExtensionOf(formStr(RetailInstanceAttributeValues))]
public final class METRetailInstanceAttributeValuesForm_Extension
{
}

Method.Source:
/// <summary>
/// update the attribute value and trigger the necessary data events for downstream processing.
/// </summary>
protected void updateAttributeValue()
{
    next updateAttributeValue();

    if (this.args().record().TableId == tableNum(CustTable))
    {
        CustTable               custTable               = this.args().record() as CustTable;
        CustomerInstanceValue   civ                     = CustomerInstanceValue::find(custTable.AccountNum, curExt());
        EcoResAttributeValue    ecoResAttributeValue    = EcoResAttributeValue::findByInstanceAttribute(civ.RecId, EcoResAttribute.RecId);
        EcoResValue             ecoResValue             = EcoResValue::find(ecoResAttributeValue.Value);
        DataEventArgs           e;
        EcoResBooleanValue      ecoResBooleanValue;
        EcoResDateTimeValue     ecoResDateTimeValue;
        EcoResFloatValue        ecoResFloatValue;
        EcoResCurrencyValue     ecoResCurrencyValue;
        EcoResIntValue          ecoResIntValue;
        EcoResTextValue         ecoResTextValue;

        switch (ecoResValue.getInstanceRelationType())
        {
            case tableStr(EcoResBooleanValue):
                ecoResBooleanValue = (ecoResValue as EcoResBooleanValue);
                BusinessEventsEntityChangeHandler::handleUpdate(ecoResBooleanValue, e);
                break;
            case tableStr(EcoResDateTimeValue):
                ecoResDateTimeValue = (ecoResValue as EcoResDateTimeValue);
                BusinessEventsEntityChangeHandler::handleUpdate(ecoResDateTimeValue, e);
                break;
            case tableStr(EcoResFloatValue):
                ecoResFloatValue = (ecoResValue as EcoResFloatValue);
                BusinessEventsEntityChangeHandler::handleUpdate(ecoResFloatValue, e);
                break;
            case tableStr(EcoResCurrencyValue):
                ecoResCurrencyValue = (ecoResValue as EcoResCurrencyValue);
                BusinessEventsEntityChangeHandler::handleUpdate(ecoResCurrencyValue, e);
                break;
            case tableStr(EcoResIntValue):
                ecoResIntValue = (ecoResValue as EcoResIntValue);
                BusinessEventsEntityChangeHandler::handleUpdate(ecoResIntValue, e);
                break;
            case tableStr(EcoResTextValue):
                ecoResTextValue = (ecoResValue as EcoResTextValue);
                BusinessEventsEntityChangeHandler::handleUpdate(ecoResTextValue, e);
                break;
        }
    }
}
